#!/bin/sh
# Verifies that the frontend assets embedded by //go:embed are present.
#
# internal/server/webui/dist is generated by `npm run build` and is not stored in
# the repository. Without it `go build` fails with the opaque
# "pattern webui/dist: no matching files found" error, so check the files the
# embed reads up front and report a build-time failure that names the fix.
set -eu

DIST_DIR=${WEBUI_DIST_DIR:-internal/server/webui/dist}
REQUIRED_FILES="index.html favicon.ico favicon.svg"

missing=""
for name in $REQUIRED_FILES; do
	if [ ! -f "$DIST_DIR/$name" ]; then
		missing="$missing $name"
	fi
done

if [ -n "$missing" ]; then
	echo "error: embedded WebUI assets are missing from $DIST_DIR:$missing" >&2
	echo "hint: run 'make webui-build' to generate them before building." >&2
	exit 1
fi

if [ -z "$(find "$DIST_DIR/assets" -type f 2>/dev/null | head -n 1)" ]; then
	echo "error: $DIST_DIR/assets contains no frontend bundle" >&2
	echo "hint: run 'make webui-build' to regenerate the frontend assets." >&2
	exit 1
fi

echo "webui assets verified: $DIST_DIR"
